package com.alpharip.staffmod.IncidentPostMortemBoard; import java.io.File;import java.io.FileWriter;import java.util.List;
public final class IncidentPostMortemExport { private IncidentPostMortemExport(){} public static boolean exportCsv(File f,List<IncidentRecord> rs){if(f==null||rs==null)return false;FileWriter w=null;try{File p=f.getParentFile();if(p!=null&&!p.exists()&&!p.mkdirs())return false;w=new FileWriter(f);w.write("id,title,category,severity,status,reporter,owner,createdAt,updatedAt,rootCause,actionCount,lessonCount\n");for(IncidentRecord r:rs){IncidentRootCause c=r.getRootCause();w.write(csv(r.getId())+","+csv(r.getTitle())+","+csv(r.getCategory().name())+","+csv(r.getSeverity().name())+","+csv(r.getStatus().name())+","+csv(r.getReporter())+","+csv(r.getOwner())+","+r.getCreatedAt()+","+r.getUpdatedAt()+","+csv(c==null?"":c.getSummary())+","+r.getActions().size()+","+r.getLessons().size()+"\n");}w.flush();return true;}catch(Exception e){return false;}finally{if(w!=null)try{w.close();}catch(Exception ignored){}}} private static String csv(String s){String v=s==null?"":s;return "\""+v.replace("\"","\"\"")+"\"";} }